def load() -> pd.DataFrame:
    with open('data/wildfire/input/nifc_human_caused_acres.csv', 'r') as f:
        lines = [f.readline() for _ in range(25)]
    return pd.DataFrame({'content': lines})

def process(human_caused_acres) -> pd.DataFrame:
    df = human_caused_acres.copy()
    df['Year'] = df['Year'].astype(int)
    df['Total'] = df['Total'].str.replace(',', '').astype(int)
    return df[['Year', 'Total']].rename(columns={'Total': 'HumanCausedAcres'})

def process(clean_suppression, clean_human_caused) -> pd.DataFrame:
    merged = clean_suppression.merge(clean_human_caused, on='Year', how='inner')
    return merged

def process(merged_data) -> pd.DataFrame:
    df = merged_data.copy()
    df['CostPerAcre'] = df['Total'] / df['HumanCausedAcres']
    return df[['Year', 'Total', 'HumanCausedAcres', 'CostPerAcre']].sort_values('CostPerAcre', ascending=False)
